"use strict";

/**
 * Find duplicate items in a list using cursor-based pagination.
 *
 * The cursor is an opaque string encoding the current offset.
 * Each page returns a batch of duplicate groups, a `nextCursor`,
 * and a `hasMore` flag so callers can iterate until exhaustion.
 */

/**
 * Encode an offset into an opaque cursor string.
 */
function encodeCursor(offset) {
  return Buffer.from(String(offset)).toString("base64");
}

/**
 * Decode an opaque cursor string back to an offset.
 * Returns -1 for invalid cursors.
 */
function decodeCursor(cursor) {
  if (typeof cursor !== "string" || cursor.length === 0) return -1;
  try {
    var n = parseInt(Buffer.from(cursor, "base64").toString("utf-8"), 10);
    return isNaN(n) || n < 0 ? -1 : n;
  } catch (_) {
    return -1;
  }
}

/**
 * Build a map of value -> [indices] for items that appear more than once.
 *
 * @param {Array} items - The list to scan.
 * @returns {Array<{value: *, indices: number[]}>} Sorted duplicate groups.
 */
function buildDuplicateGroups(items) {
  var seen = Object.create(null);
  for (var i = 0; i < items.length; i++) {
    var key = toStableKey(items[i]);
    if (!seen[key]) seen[key] = { value: items[i], indices: [] };
    seen[key].indices.push(i);
  }

  var groups = [];
  for (var k in seen) {
    if (seen[k].indices.length > 1) {
      groups.push(seen[k]);
    }
  }
  // Deterministic order: by first occurrence index
  groups.sort(function (a, b) { return a.indices[0] - b.indices[0]; });
  return groups;
}

/**
 * Produce a stable string key for any JS value (handles objects/arrays).
 */
function toStableKey(value) {
  if (value === null) return "null";
  if (value === undefined) return "undefined";
  if (typeof value === "object") {
    try {
      return JSON.stringify(value, Object.keys(value).sort());
    } catch (_) {
      return String(value);
    }
  }
  return typeof value + ":" + String(value);
}

/**
 * Find duplicates in `items`, returned in cursor-based pages.
 *
 * @param {Array} items - The list to scan for duplicates.
 * @param {Object} [options]
 * @param {string} [options.cursor] - Opaque cursor from a previous call (omit for the first page).
 * @param {number} [options.pageSize=10] - Maximum duplicate groups per page.
 * @returns {{ duplicates: Array<{value: *, indices: number[]}>, nextCursor: string|null, hasMore: boolean }}
 */
function find_duplicates(items, options) {
  if (!Array.isArray(items)) {
    throw new TypeError("items must be an array");
  }

  var opts = options || {};
  var pageSize = typeof opts.pageSize === "number" && opts.pageSize > 0
    ? Math.floor(opts.pageSize)
    : 10;

  var startOffset = 0;
  if (opts.cursor !== undefined && opts.cursor !== null) {
    startOffset = decodeCursor(opts.cursor);
    if (startOffset < 0) {
      throw new RangeError("Invalid cursor");
    }
  }

  var groups = buildDuplicateGroups(items);

  var page = groups.slice(startOffset, startOffset + pageSize);
  var nextOffset = startOffset + pageSize;
  var hasMore = nextOffset < groups.length;

  return {
    duplicates: page,
    nextCursor: hasMore ? encodeCursor(nextOffset) : null,
    hasMore: hasMore,
  };
}

module.exports = { find_duplicates, encodeCursor, decodeCursor, toStableKey };

"use strict";

var { find_duplicates, encodeCursor, decodeCursor, toStableKey } = require("./find_duplicates");

// ---------------------------------------------------------------------------
// Test helpers
// ---------------------------------------------------------------------------

var _passed = 0;
var _failed = 0;

function assert(condition, name) {
  if (condition) {
    _passed++;
    console.log("  PASS: " + name);
  } else {
    _failed++;
    console.log("  FAIL: " + name);
  }
}

function assertThrows(fn, expectedType, name) {
  try {
    fn();
    _failed++;
    console.log("  FAIL: " + name + " (did not throw)");
  } catch (err) {
    assert(err instanceof expectedType, name + " (" + err.constructor.name + ")");
  }
}

// ---------------------------------------------------------------------------
// Cursor encoding / decoding
// ---------------------------------------------------------------------------

function test_cursor_roundtrip() {
  console.log("=== Cursor: encode/decode roundtrip ===");
  for (var i = 0; i <= 100; i += 5) {
    assert(decodeCursor(encodeCursor(i)) === i, "roundtrip offset " + i);
  }
}

function test_cursor_decode_invalid() {
  console.log("=== Cursor: invalid cursors ===");
  assert(decodeCursor(null) === -1, "null cursor");
  assert(decodeCursor(undefined) === -1, "undefined cursor");
  assert(decodeCursor("") === -1, "empty string cursor");
  assert(decodeCursor("not-base64-@@@") === -1, "garbage cursor");
  assert(decodeCursor(encodeCursor(-5)) === -1, "negative offset cursor");
}

function test_cursor_is_opaque() {
  console.log("=== Cursor: cursor is opaque base64 ===");
  var c = encodeCursor(42);
  assert(typeof c === "string", "cursor is a string");
  assert(c.length > 0, "cursor is non-empty");
  // Should not be plain text
  assert(c !== "42", "cursor is not the raw number");
}

// ---------------------------------------------------------------------------
// toStableKey
// ---------------------------------------------------------------------------

function test_stable_key_primitives() {
  console.log("=== toStableKey: primitives ===");
  assert(toStableKey(42) === "number:42", "integer key");
  assert(toStableKey("hello") === "string:hello", "string key");
  assert(toStableKey(true) === "boolean:true", "boolean key");
  assert(toStableKey(null) === "null", "null key");
  assert(toStableKey(undefined) === "undefined", "undefined key");
}

function test_stable_key_objects() {
  console.log("=== toStableKey: objects ===");
  assert(toStableKey({ a: 1, b: 2 }) === toStableKey({ b: 2, a: 1 }), "key order irrelevant");
  assert(toStableKey([1, 2]) !== toStableKey([2, 1]), "array order matters");
}

// ---------------------------------------------------------------------------
// Empty / trivial inputs
// ---------------------------------------------------------------------------

function test_empty_list() {
  console.log("=== Trivial: empty list ===");
  var r = find_duplicates([]);
  assert(r.duplicates.length === 0, "no duplicates");
  assert(r.hasMore === false, "hasMore is false");
  assert(r.nextCursor === null, "nextCursor is null");
}

function test_single_item() {
  console.log("=== Trivial: single item ===");
  var r = find_duplicates([1]);
  assert(r.duplicates.length === 0, "no duplicates");
  assert(r.hasMore === false, "hasMore is false");
}

function test_no_duplicates() {
  console.log("=== Trivial: no duplicates ===");
  var r = find_duplicates(["a", "b", "c"]);
  assert(r.duplicates.length === 0, "no duplicates");
  assert(r.hasMore === false, "hasMore is false");
}

function test_all_unique_numbers() {
  console.log("=== Trivial: all unique numbers ===");
  var r = find_duplicates([10, 20, 30, 40, 50]);
  assert(r.duplicates.length === 0, "no duplicates");
}

// ---------------------------------------------------------------------------
// Basic duplicate detection
// ---------------------------------------------------------------------------

function test_simple_string_duplicates() {
  console.log("=== Basic: string duplicates ===");
  var r = find_duplicates(["alice", "bob", "alice", "charlie", "bob"]);
  assert(r.duplicates.length === 2, "two duplicate groups");
  assert(r.duplicates[0].value === "alice", "first group is alice");
  assert(r.duplicates[0].indices.length === 2, "alice appears twice");
  assert(r.duplicates[1].value === "bob", "second group is bob");
  assert(r.duplicates[1].indices.length === 2, "bob appears twice");
}

function test_integer_duplicates() {
  console.log("=== Basic: integer duplicates ===");
  var r = find_duplicates([1, 2, 3, 2, 4, 1, 1]);
  assert(r.duplicates.length === 2, "two duplicate groups");

  var map = {};
  r.duplicates.forEach(function (d) { map[d.value] = d.indices.length; });
  assert(map[1] === 3, "1 appears 3 times");
  assert(map[2] === 2, "2 appears 2 times");
}

function test_all_same() {
  console.log("=== Basic: all same ===");
  var r = find_duplicates(["x", "x", "x", "x"]);
  assert(r.duplicates.length === 1, "one duplicate group");
  assert(r.duplicates[0].value === "x", "value is x");
  assert(r.duplicates[0].indices.length === 4, "4 occurrences");
}

function test_duplicate_objects() {
  console.log("=== Basic: duplicate objects ===");
  var data = [{ id: 1, name: "a" }, { id: 2, name: "b" }, { id: 1, name: "a" }];
  var r = find_duplicates(data);
  assert(r.duplicates.length === 1, "one duplicate group");
  assert(r.duplicates[0].value.id === 1, "duplicate id is 1");
}

function test_duplicate_arrays() {
  console.log("=== Basic: duplicate arrays ===");
  var data = [[1, 2], [3, 4], [1, 2]];
  var r = find_duplicates(data);
  assert(r.duplicates.length === 1, "one duplicate group");
  assert(r.duplicates[0].value[0] === 1, "first element is 1");
}

function test_duplicate_nulls() {
  console.log("=== Basic: duplicate nulls ===");
  var r = find_duplicates([null, null, null]);
  assert(r.duplicates.length === 1, "one duplicate group");
  assert(r.duplicates[0].value === null, "value is null");
  assert(r.duplicates[0].indices.length === 3, "3 occurrences");
}

function test_duplicate_booleans() {
  console.log("=== Basic: duplicate booleans ===");
  var r = find_duplicates([true, false, true, false, true]);
  assert(r.duplicates.length === 2, "two duplicate groups");
}

function test_indices_are_correct() {
  console.log("=== Basic: indices are correct ===");
  var r = find_duplicates(["a", "b", "a", "c", "b", "a"]);
  var aGroup = r.duplicates.filter(function (d) { return d.value === "a"; })[0];
  assert(aGroup.indices[0] === 0, "first a at index 0");
  assert(aGroup.indices[1] === 2, "second a at index 2");
  assert(aGroup.indices[2] === 5, "third a at index 5");
}

// ---------------------------------------------------------------------------
// Pagination
// ---------------------------------------------------------------------------

function test_single_page() {
  console.log("=== Pagination: all fit in one page ===");
  var r = find_duplicates(["a", "b", "a", "b"], { pageSize: 100 });
  assert(r.duplicates.length === 2, "two groups fit in one page");
  assert(r.hasMore === false, "hasMore is false");
  assert(r.nextCursor === null, "nextCursor is null");
}

function test_multi_page_traversal() {
  console.log("=== Pagination: multi-page traversal ===");
  // 5 duplicate groups with pageSize=2 -> 3 pages
  var data = ["a", "b", "c", "d", "e", "a", "b", "c", "d", "e"];
  var allGroups = [];
  var cursor = undefined;
  var pages = 0;

  do {
    var r = find_duplicates(data, { cursor: cursor, pageSize: 2 });
    allGroups = allGroups.concat(r.duplicates);
    cursor = r.nextCursor;
    pages++;
  } while (r.hasMore);

  assert(allGroups.length === 5, "collected all 5 duplicate groups");
  assert(pages === 3, "took 3 pages");
}

function test_page_size_one() {
  console.log("=== Pagination: pageSize=1 ===");
  var data = [1, 2, 3, 1, 2, 3];
  var r1 = find_duplicates(data, { pageSize: 1 });
  assert(r1.duplicates.length === 1, "first page has 1 group");
  assert(r1.hasMore === true, "hasMore is true");
  assert(r1.nextCursor !== null, "nextCursor is not null");

  var r2 = find_duplicates(data, { cursor: r1.nextCursor, pageSize: 1 });
  assert(r2.duplicates.length === 1, "second page has 1 group");
  assert(r2.duplicates[0].value !== r1.duplicates[0].value, "different group");

  var r3 = find_duplicates(data, { cursor: r2.nextCursor, pageSize: 1 });
  assert(r3.duplicates.length === 1, "third page has 1 group");
  assert(r3.hasMore === false, "no more after third page");
}

function test_cursor_at_end_returns_empty() {
  console.log("=== Pagination: cursor past end ===");
  var data = ["a", "b", "a", "b"];
  // Get all groups first
  var r1 = find_duplicates(data, { pageSize: 10 });
  // Use the nextCursor (which points past the end)
  var r2 = find_duplicates(data, { cursor: r1.nextCursor, pageSize: 10 });
  // Actually nextCursor is null when hasMore is false, so test with a decoded cursor past end
  var r3 = find_duplicates(data, { cursor: encodeCursor(999), pageSize: 10 });
  assert(r3.duplicates.length === 0, "empty page past end");
  assert(r3.hasMore === false, "hasMore false past end");
}

function test_default_page_size() {
  console.log("=== Pagination: default pageSize is 10 ===");
  // Create 15 duplicate groups
  var data = [];
  for (var i = 0; i < 15; i++) {
    data.push(i, i); // each number appears twice
  }
  var r = find_duplicates(data);
  assert(r.duplicates.length === 10, "default page returns 10 groups");
  assert(r.hasMore === true, "hasMore is true");
}

function test_no_options() {
  console.log("=== Pagination: no options ===");
  var r = find_duplicates(["a", "a"]);
  assert(r.duplicates.length === 1, "works with no options");
}

function test_empty_options() {
  console.log("=== Pagination: empty options ===");
