// Error handling
// ---------------------------------------------------------------------------

function test_invalid_items_type() {
  console.log("=== Errors: invalid items type ===");
  assertThrows(function () { find_duplicates("not an array"); }, TypeError, "string throws TypeError");
  assertThrows(function () { find_duplicates(42); }, TypeError, "number throws TypeError");
  assertThrows(function () { find_duplicates(null); }, TypeError, "null throws TypeError");
  assertThrows(function () { find_duplicates(undefined); }, TypeError, "undefined throws TypeError");
